import React, { useEffect, useState } from 'react';
import axios from 'axios';

function Wishlist() {
  const [wishlist, setWishlist] = useState([]);

  const userId = localStorage.getItem('userId'); // Get user ID (store it during login)

  const fetchWishlist = async () => {
    const res = await axios.get(`http://localhost:5000/api/wishlist/${userId}`);
    setWishlist(res.data);
  };

  const removeFromWishlist = async (productId) => {
    await axios.post(`http://localhost:5000/api/wishlist/remove`, {
      userId,
      productId,
    });
    fetchWishlist();
  };

  useEffect(() => {
    fetchWishlist();
  }, []);

  return (
    <div style={{ padding: '20px' }}>
      <h2>Your Wishlist</h2>
      {wishlist.length === 0 ? (
        <p>No items in wishlist</p>
      ) : (
        <table border="1" cellPadding="10">
          <thead>
            <tr>
              <th>Name</th><th>Description</th><th>Qty</th><th>Price</th><th>Category</th><th>Action</th>
            </tr>
          </thead>
          <tbody>
            {wishlist.map((item) => (
              <tr key={item._id}>
                <td>{item.name}</td>
                <td>{item.description}</td>
                <td>{item.quantity}</td>
                <td>{item.price}</td>
                <td>{item.category}</td>
                <td>
                  <button onClick={() => removeFromWishlist(item._id)}>Remove</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default Wishlist;
